mapper.select:
SELECT s.mcp_server_id, s.server_code, s.server_name, s.description, s.status, s.revision, published.mcp_server_version_id AS published_version_id, published.version_no AS published_version_no, draft.mcp_server_version_id AS draft_version_id, ( SELECT COUNT(DISTINCT t.tool_id) FROM squad_chat.sq_mcp_server_version mv JOIN squad_chat.sq_tool_version tv ON tv.mcp_server_version_id = mv.mcp_server_version_id JOIN squad_chat.sq_tool t ON t.tool_id = tv.tool_id WHERE mv.mcp_server_id = s.mcp_server_id AND tv.status = 'PUBLISHED' AND t.status = 'ENABLED' ) AS usage_count, s.last_update_time FROM squad_chat.sq_mcp_server s LEFT JOIN LATERAL ( SELECT v.mcp_server_version_id, v.version_no FROM squad_chat.sq_mcp_server_version v WHERE v.mcp_server_id = s.mcp_server_id AND v.status = 'PUBLISHED' ORDER BY v.version_no DESC LIMIT 1 ) published ON TRUE LEFT JOIN squad_chat.sq_mcp_server_version draft ON draft.mcp_server_id = s.mcp_server_id AND draft.status = 'DRAFT'
s.mcp_server_id = #{mcpServerId}
ORDER BY s.last_update_time DESC, s.id DESC
